--
-- Name: sbom_score(text); Type: FUNCTION; Schema: public; Owner: sbom
--

CREATE FUNCTION public.sbom_score(raw text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  n numeric;
BEGIN
  IF raw IS NULL OR btrim(raw) = '' THEN
    RETURN 0;
  END IF;
  n := raw::numeric;
  IF n < 0 THEN
    RETURN 0;
  END IF;
  IF n > 10 THEN
    RETURN 10;
  END IF;
  RETURN round(n, 1);
EXCEPTION WHEN others THEN
  RETURN 0;
END;
$$;


